void ExtensionInfoPrivateAsyncWaiter::GetSystemProperties(
    const std::vector<std::string>& property_names, ::base::Value* out_properties) {
  base::RunLoop loop;
  proxy_->GetSystemProperties(std::move(property_names),
      base::BindOnce(
          [](base::RunLoop* loop,
             ::base::Value* out_properties
,
             ::base::Value properties) {*out_properties = std::move(properties);
            loop->Quit();
          },
          &loop,
          out_properties));
  loop.Run();
}

::base::Value ExtensionInfoPrivateAsyncWaiter::GetSystemProperties(
    const std::vector<std::string>& property_names) {
  ::base::Value async_wait_result;
  GetSystemProperties(std::move(property_names),&async_wait_result);
  return async_wait_result;
}

